import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isWarping, setIsWarping] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsWarping(true), 3500);
    const finish = setTimeout(onComplete, 4500);
    return () => { clearTimeout(timer); clearTimeout(finish); };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#FFF24DA] flex items-center justify-center relative overflow-hidden">

      {/* 1. TEXTURE: Industrial Grain */}
      <div className="absolute inset-0 grain-overlay pointer-events-none" />

      {/* 2. THE BLADE: One single sharp line of Lime light
      <motion.div 
        initial={{ height: 0 }}
        animate={{ height: "100vh" }}
        transition={{ duration: 1.5, ease: "easeInOut" }}
        className="absolute w-[1px] bg-gradient-to-b from-transparent via-[#CAD23C]/40 to-transparent"
      /> */}

      <div className={isWarping ? "animate-warp" : "animate-reveal"}>
        <div className="flex flex-col items-center">

          {/* THE LOGO: Massive, Dark, Imposing */}
          <div className="relative flex items-center group">
            <motion.h1 
              initial={{ letterSpacing: "-0.5em", opacity: 0 }}
              animate={{ letterSpacing: "0.1em", opacity: 1 }}
              transition={{ duration: 2, ease: "easeOut" }}
              className="text-[12rem] md:text-[20rem] font-[1000] text-[#AB1717] italic tracking-tighter leading-none"
            >
              T
              <span className="text-[#AB1717] relative inline-block mx-[-10px] drop-shadow-[0_0_30px_rgba(255,91,3,0.4)]">
                2
              </span>
              T
            </motion.h1>
          </div>

          {/* THE SUBTITLE: Swiggy/Apple Minimalist Style */}
          <motion.div 
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 0.6, y: 0 }}
            transition={{ delay: 1.5, duration: 1 }}
            className="flex items-center gap-8 mt-[-30px]"
          >
            <div className="h-[1px] w-20 bg-gradient-to-r from-transparent to-[#FDFAD8]" />
            <span className="text-[#FDFAD8] font-black text-2xl tracking-[1em] uppercase italic ml-[1em]">
              Worker
            </span>
            <div className="h-[1px] w-20 bg-gradient-to-l from-transparent to-[#FDFAD8]" />
          </motion.div>
        </div>
      </div>

      {/* 3. TACTICAL OVERLAY (The "Pro" Touch) */}
      <div className="absolute bottom-12 w-full px-16 flex justify-between items-end">
        <div className="flex flex-col font-mono text-[9px] text-[#CAD23C] opacity-30 gap-1">
          <span>LAT_REF: 40.7128N</span>
          <span>LON_REF: 74.0060W</span>
          <span className="text-white opacity-100 font-black">STABLE_CONNECTION_V4</span>
        </div>

        {/* Minimal Progress Percent */}
        <motion.span 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="text-[#FF5B03] font-black text-xl italic"
        >
          {/* Placeholder for progress feeling */}
          00.04
        </motion.span>
      </div>
    </div>
  );
};

export default WorkerSplash;
